dtsPropsFor.Button:
/** Style visuel. `gold` = action principale, `whatsapp` = vert de la marque. @default "gold" */
  variant?: "gold" | "outline" | "ghost" | "whatsapp";
  /** Hauteur du bouton : 44px / 48px / 56px. @default "md" */
  size?: "sm" | "md" | "lg";
  /** Libellé. Rendu en majuscules et interlettré par le composant. */
  children: React.ReactNode;
  className?: string;
  type?: "button" | "submit" | "reset";
  disabled?: boolean;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  "aria-label"?: string;

dtsPropsFor.ButtonLink:
/** Destination du lien (`#ancre`, `tel:`, `https://wa.me/...`). Requis. */
  href: string;
  /** Style visuel. `gold` = action principale, `whatsapp` = vert de la marque. @default "gold" */
  variant?: "gold" | "outline" | "ghost" | "whatsapp";
  /** Hauteur du bouton : 44px / 48px / 56px. @default "md" */
  size?: "sm" | "md" | "lg";
  /** Libellé. Rendu en majuscules et interlettré par le composant. */
  children: React.ReactNode;
  className?: string;
  target?: string;
  rel?: string;
  "aria-label"?: string;

dtsPropsFor.SectionHeading:
/** Sur-titre court en doré interlettré, au-dessus du titre. */
  eyebrow: string;
  /** Première ligne du titre, en blanc. */
  title: string;
  /** Seconde ligne. Omise, le titre tient sur une ligne. Voir `accent`. */
  titleAccent?: string;
  /** Traitement de `titleAccent` : dégradé doré ou blanc. Réserver `gold` aux
   * sections pivots — une page ne devrait pas porter plus de deux accents dorés.
   * @default "gold" */
  accent?: "gold" | "plain";
  /** Échelle du titre : `lg` pour une section pivot, `md` pour le rythme courant. @default "lg" */
  size?: "md" | "lg";
  /** Paragraphe d'introduction sous le filet doré. */
  description?: string;
  /** @default "center" */
  align?: "left" | "center";
  className?: string;

dtsPropsFor.Reveal:
/** Contenu révélé à l'entrée dans le viewport. */
  children: React.ReactNode;
  /** Délai avant l'apparition, en secondes — sert à cascader une liste. @default 0 */
  delay?: number;
  /** Translation verticale initiale, en pixels. @default 24 */
  y?: number;
  /** Balise rendue. Utiliser `li` dans une liste. @default "div" */
  as?: "div" | "li" | "section";
  className?: string;

dtsPropsFor.DemoNotice:
/** Texte de la mention. Chaîne simple, pas de JSX. */
  children: string;
  /** `gold` = mention mise en avant ; `subtle` = mention neutre, quand plusieurs
   * sections d'affilée en portent une. @default "gold" */
  tone?: "gold" | "subtle";
  className?: string;
